    captcha_hits: int = 0
    circuit_breaker_opens: int = 0
    rl_suggested_pivot: str = ""

    # F2-3: DuckDB in-process mode telemetry — "inprocess" | "subprocess" | "legacy"
    duckdb_mode: str = "unknown"

